<template><section class="chart-section" :class="{full}"><header><h2><TrendingUp :size="16" :stroke-width="1.7"/>{{full?'榜单点歌':'热榜推荐'}}</h2><div class="chart-tabs"><button v-for="s in quickOptions" :key="s.id" :class="{on:source===s.id}" @click="source=s.id">{{s.label}}</button></div><button ref="pickerTrigger" class="chart-select" aria-label="选择榜单" :aria-expanded="pickerOpen" @click="openPicker">{{source==='all'?'选择榜单':options.find(s=>s.id===source)?.label||'选择榜单'}} ▾</button><button class="section-tool" :aria-busy="data.loading" :aria-disabled="data.loading" aria-label="更新榜单" @click="!data.loading&&load(true)"><RefreshCw :size="14"/></button><button v-if="!full" @click="router.push({name:'ranking'})">更多 ›</button></header><PagedCarousel :items="items" :query-key="source" :page-size="full?8:6" :columns="2" :controls="full"><template #default="{items:rows}"><button v-for="item in rows" :key="item.source+item.rank" class="chart-song" @click="order(item)"><span class="chart-rank">{{item.rank}}</span><div><b>{{item.song?.title||item.title}}</b><small>{{item.song?.artist||item.artists.join(' / ')}}</small></div><span class="availability">{{isOrdered(item)?'已点':item.available?(player.isPlaying?'＋ 点歌':'立即唱'):item.status==='confirm'?'确认版本':'B站找歌'}}</span></button></template></PagedCarousel><footer class="chart-source">{{sourceLabel}} · {{asOf}}<span v-if="data.sources?.some(s=>s.error)"> · 部分来源暂不可用</span></footer><Teleport to="body"><div v-if="pickerOpen" class="chart-picker-mask" @click.self="closePicker" @keydown.stop="pickerKey"><section ref="pickerRoot" class="chart-picker" role="dialog" aria-modal="true" aria-label="选择音乐榜单"><header><h2>选择音乐榜单</h2><button aria-label="关闭" @click="closePicker">关闭</button></header><div class="chart-picker-grid"><button v-for="s in options" :key="s.id" :data-chart="s.id" :aria-pressed="source===s.id" :class="{selected:source===s.id}" @click="selectChart(s.id)">{{s.label}}<span v-if="source===s.id"> ✓</span></button></div><p>方向键选择 · 确认键切换 · 返回键关闭</p></section></div><div v-if="choosing" class="chart-match-mask" @click.self="choosing=null"><section role="dialog" aria-modal="true" aria-label="确认原唱版本"><header><h2>为《{{choosing.title}}》选择曲库版本</h2><button aria-label="关闭" @click="choosing=null">关闭</button></header><p>同名歌曲可能不是同一首，确认后保存关联。</p><button @click="online(choosing)">曲库没有合适版本？到B站找MV ›</button><button v-for="song in candidates" :key="song.id" @click="choose(song)">{{song.title}} · {{song.artist}} · {{song.edition}}</button></section></div></Teleport></section></template>
<script setup>
import {ref,computed,nextTick,onMounted,onUnmounted} from 'vue'
import {TrendingUp,RefreshCw} from 'lucide-vue-next'
import PagedCarousel from './PagedCarousel.vue'
import {useRouter} from 'vue-router';import {usePlayerStore} from '../stores/player'
const props=defineProps({full:Boolean}),router=useRouter(),player=usePlayerStore()
import api from '../api/client';import {useToast} from '../composables/useToast';import {useSwipePages} from '../composables/useSwipePages'
const choosing=ref(null),candidates=ref([])
const {toast}=useToast(),data=ref({loading:true,sources:[],items:[],recommendations:[]}),source=ref('all'),page=ref(0)
const quickOptions=computed(()=>[{id:'all',label:'综合'},{id:'qq',label:'抖音'},{id:'netease_rising',label:'飙升'},...(props.full?[{id:'netease_new',label:'新歌'}]:[])])
const options=computed(()=>[{id:'all',label:'综合推荐'},...(data.value.sources||[]).map(s=>({id:s.id,label:s.id==='qq'?'抖音热歌':s.label}))])
const pickerOpen=ref(false),pickerRoot=ref(null),pickerTrigger=ref(null)
async function openPicker(){pickerOpen.value=true;window.Woniu?.chartPickerOpen?.(true);await nextTick();pickerRoot.value?.querySelector(`[data-chart="${source.value}"]`)?.focus()}
async function closePicker(){pickerOpen.value=false;window.Woniu?.chartPickerOpen?.(false);await nextTick();pickerTrigger.value?.focus()}
function selectChart(id){source.value=id;closePicker()}
function pickerKey(event){
 const buttons=[...(pickerRoot.value?.querySelectorAll('[data-chart]')||[])],current=buttons.indexOf(document.activeElement),close=pickerRoot.value?.querySelector('[aria-label="关闭"]')
 if(['Escape','Backspace','BrowserBack'].includes(event.key)){event.preventDefault();closePicker();return}
 if(['Enter',' '].includes(event.key)){event.preventDefault();document.activeElement?.click();return}
 let target=current
 if(event.key==='Tab'){event.preventDefault();const controls=[...buttons,close],i=controls.indexOf(document.activeElement);controls[(i+(event.shiftKey?-1:1)+controls.length)%controls.length]?.focus();return}
 if(!event.key.startsWith('Arrow'))return
 event.preventDefault()
 if(current<0){buttons[0]?.focus();return}
 if(event.key==='ArrowUp'){if(current<2){close?.focus();return};target=current-2}
 if(event.key==='ArrowDown')target=Math.min(buttons.length-1,current+2)
 if(event.key==='ArrowLeft'&&current%2===1)target=current-1
 if(event.key==='ArrowRight'&&current%2===0)target=Math.min(buttons.length-1,current+1)
 buttons[target]?.focus();buttons[target]?.scrollIntoView?.({block:'nearest'})
}
const items=computed(()=>source.value==='all'?data.value.recommendations||[]:(data.value.items||[]).filter(x=>x.source===source.value))
const pages=computed(()=>Math.max(1,Math.ceil(items.value.length/2))),visible=computed(()=>items.value.slice(page.value*2,page.value*2+2))
const sourceLabel=computed(()=>source.value==='all'?'来源：QQ音乐 / 网易云 / 酷狗':(data.value.sources||[]).find(s=>s.id===source.value)?.label||'公开音乐榜单')
const asOf=computed(()=>source.value==='all'?'每小时检查 · '+(data.value.checkedAt?new Date(data.value.checkedAt).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})+'已检查':'正在检查'):(data.value.sources||[]).find(s=>s.id===source.value)?.updated||'')
function next(){if(page.value+1<pages.value)page.value++}function previous(){if(page.value)page.value--}
const {touchStart,touchEnd}=useSwipePages(previous,next)
async function load(refresh=false){try{data.value=await api.discovery(refresh===true)}catch(e){data.value.loading=false;toast(e.message)}}
function isOrdered(item){return item.song?.id!=null&&player.orderedSongIds.has(String(item.song.id))}
function online(item){choosing.value=null;router.push({name:'bilibili',query:{keyword:[item.title,...item.artists,'MV'].join(' '),matchTitle:item.title,matchArtists:JSON.stringify(item.artists)}})}
async function order(item){if(isOrdered(item)){toast('这首歌已点');return}if(!item.available){if(item.status==='confirm'){choosing.value=item;candidates.value=await api.chartCandidates(item.title)}else online(item);return}try{player.applySnapshot(await api.control('order',{song_id:item.song.id}));toast('已加入队列')}catch(e){toast(e.message)}}
async function choose(song){try{data.value=await api.chartMatch(choosing.value.title,choosing.value.artists,song.id);choosing.value=null;toast('已保存原唱版本关联')}catch(e){toast(e.message)}}
let timer,lastCheck=Date.now();onMounted(()=>{load();window.addEventListener('discovery-updated',load);timer=setInterval(()=>{if(document.visibilityState==='visible'&&(data.value.loading||Date.now()-lastCheck>=60000)){lastCheck=Date.now();load()}},2000)});onUnmounted(()=>{window.Woniu?.chartPickerOpen?.(false);clearInterval(timer);window.removeEventListener('discovery-updated',load)})
</script>
<style scoped>
.chart-section{height:100%;min-height:0;display:flex;flex-direction:column;background:var(--panel);border:1px solid var(--glass-border);border-radius:16px;padding:12px 14px;box-shadow:var(--shadow)}.chart-section>header{display:flex;align-items:center;gap:8px;flex:none;margin-bottom:8px;min-height:30px}.chart-section h2{font-size:14px;display:flex;align-items:center;gap:7px;white-space:nowrap;font-weight:600;margin-right:auto}.chart-section h2 svg{color:var(--gold)}.chart-section button{border-radius:7px;font-size:10px}.chart-section>header>button{padding:6px 8px;color:var(--dim);background:var(--panel2);border:1px solid var(--glass-border);min-height:28px}.section-tool{display:grid;place-items:center}.chart-select{max-width:130px;min-width:70px;color:var(--gold);background:var(--panel2);border:1px solid var(--line);border-radius:7px;padding:5px;font-size:10px}.chart-tabs{display:flex;gap:2px;padding:3px;background:var(--recess);border:1px solid var(--line);border-radius:8px}.chart-tabs button{padding:4px 7px;color:var(--dim2);font-size:10px;min-height:23px}.chart-tabs .on{background:var(--selected);color:var(--gold);box-shadow:0 1px 4px #0001}.paged-carousel{flex:1;min-height:0}.chart-song{display:flex;align-items:center;gap:8px;text-align:left;margin:4px 0;padding:9px 10px;min-height:0;background:var(--tile);border:1px solid var(--glass-border);border-radius:11px!important;box-shadow:inset 0 1px 0 var(--highlight)}.chart-song>div{min-width:0;flex:1}.chart-song b{display:block;font-size:13px;line-height:1.4;font-weight:600;white-space:nowrap;text-overflow:ellipsis;overflow:hidden}.chart-song small{display:block;color:var(--dim);font-size:10px;line-height:1.4;margin-top:5px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.chart-rank{color:var(--gold);font-size:20px;min-width:19px;font-family:Georgia,serif;font-style:italic;font-weight:400}.availability{font-size:9px;color:var(--gold);width:30px;flex:none;text-align:right;line-height:1.5}.chart-source{flex:none;font-size:8px;color:var(--dim2);margin-top:7px;white-space:nowrap;text-overflow:ellipsis;overflow:hidden}.full{background:transparent;border:0;padding:0;box-shadow:none}.full .chart-song{padding:5px 12px;margin:3px 0}.full .chart-song b{font-size:15px;line-height:1.3}.full .chart-song small{font-size:11px;line-height:1.3;margin-top:3px}.full>header{margin-bottom:8px}.full h2{font-size:19px}.full .chart-tabs button{font-size:12px;padding:5px 14px}.full .chart-select{max-width:220px;font-size:12px}.chart-match-mask{position:fixed;inset:0;background:#090b11bd;z-index:130;display:grid;place-items:center}.chart-match-mask section{background:var(--panel);border:1px solid var(--glass-border);border-radius:18px;padding:24px;width:70vw;max-height:80vh;overflow:auto;box-shadow:var(--shadow)}.chart-match-mask header{display:flex;align-items:center;justify-content:space-between}.chart-match-mask h2{font-size:20px}.chart-match-mask p{color:var(--dim);font-size:13px;margin:12px 0}.chart-match-mask button{min-height:46px;background:var(--tile);border:1px solid var(--glass-border);border-radius:10px;padding:12px;margin:6px 0;display:block;width:100%;text-align:left}.chart-match-mask header button{width:auto}
</style>

<style scoped>.chart-picker-mask{position:fixed;inset:0;z-index:140;background:#090b11c9;display:grid;place-items:center}.chart-picker{width:min(650px,88vw);max-height:84vh;overflow:auto;background:var(--panel);border:1px solid var(--glass-border);border-radius:18px;padding:18px;box-shadow:var(--shadow)}.chart-picker header{display:flex;align-items:center;justify-content:space-between;margin-bottom:12px}.chart-picker h2{font-size:20px}.chart-picker button{border:1px solid var(--line);border-radius:9px;background:var(--tile);color:var(--text);padding:10px 14px;min-height:42px}.chart-picker-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.chart-picker-grid button{font-size:16px;text-align:left}.chart-picker .selected{color:var(--gold);border-color:var(--gold)}.chart-picker button:focus{outline:3px solid var(--gold);outline-offset:2px;background:var(--selected)}.chart-picker p{font-size:12px;color:var(--dim);margin:12px 0 0}.chart-section>header>.chart-select{max-width:88px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.full>header>.chart-select{max-width:220px}</style>
